INSERT INTO pyq_collections (id, slug, subject, title, exam_paper, year, is_premium, question_count, sort_order)
VALUES ('963c3b26-5d0a-4d54-9f39-760cfeda1427', 'upsc-geography-optional-paper-2-pyq', 'geography', 'UPSC Geography Optional Paper II — PYQ & Model Answers (2023)', 'paper-2', 2023, true, 27, 2);

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('10c3fb96-4f9b-42b4-a323-d5eb7e2ca921', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 1, 'A', '1(a)', 20, 30, 'On the outline map of India provided, mark the location of all of the following. Write in your QCA Booklet the significance of these locations, whether physical/commercial/economic/ecological/environmental/cultural, in not more than 30 words for each entry: (i) Nathula (ii) Hutti (iii) Ross Island (iv) Moreh (v) Ramappa (vi) Namdapha National Park (vii) Sela Tunnel (viii) Ennore Port (ix) Ramagundam (x) Betwa River');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('10c3fb96-4f9b-42b4-a323-d5eb7e2ca921', '(i) Nathula: A high-altitude Himalayan pass (Sikkim) on the historic Silk Route to Tibet/China; reopened in 2006 for border trade, it holds major strategic and commercial significance for Indo-China trade and defence.

(ii) Hutti: A town in Raichur district, Karnataka, site of the Hutti Gold Mines, India''s oldest and among its few operational gold mines -- significant for domestic mineral/economic resource production.

(iii) Ross Island: In the Andaman archipelago (renamed Netaji Subhas Chandra Bose Dweep), the former British administrative headquarters of the penal colony; significant for colonial-era heritage, tourism, and its ecological setting amid coral reefs.

(iv) Moreh: A border town in Manipur on the India-Myanmar border, key node of the Trans-Asian Highway/India-Myanmar-Thailand corridor; strategically and commercially vital for India''s Act East Policy and border trade.

(v) Ramappa: A 13th-century Kakatiya-era temple in Telangana, a UNESCO World Heritage Site (2021); significant for cultural/architectural heritage and heritage tourism.

(vi) Namdapha National Park: In Arunachal Pradesh, India''s largest protected area by size, a biodiversity hotspot with four big cat species; significant ecologically for its exceptional biodiversity and as a Project Tiger reserve.

(vii) Sela Tunnel: A strategic all-weather tunnel in Arunachal Pradesh connecting Tawang to the rest of India through the Sela Pass; significant for military logistics and year-round connectivity to a sensitive border region.

(viii) Ennore Port: A major port near Chennai, Tamil Nadu (Kamarajar Port), specialising in coal, and other bulk cargo handling; significant commercially for Tamil Nadu''s energy and industrial supply chain.

(ix) Ramagundam: In Telangana, site of a major NTPC thermal power station and fertiliser plant on the Godavari; significant economically for regional power generation and industry.

(x) Betwa River: A tributary of the Yamuna flowing through Madhya Pradesh and Uttar Pradesh; significant for the Ken-Betwa river-linking project and irrigation/water-resource development in the Bundelkhand region.', 'In the real exam this is a map-based question: candidates mark each location''s precise position on a physical outline map of India as well as writing the significance note (capped at 30 words per entry) -- location accuracy on the map itself carries separate marks from the written significance, so map practice is essential exam preparation, not just factual recall of significance.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q1(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('62885209-afed-4ed6-ab76-f6481f036598', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 2, 'A', '1(b)', 10, 150, 'Describe the origin, distribution and economic significance of Gondwana system of rocks in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('62885209-afed-4ed6-ab76-f6481f036598', 'The Gondwana system comprises fluvial/lacustrine sedimentary rocks deposited in India''s Permian-to-Cretaceous era (roughly 300-100 million years ago) in linear, fault-bounded (rift) river-valley basins formed as part of the ancient Gondwanaland supercontinent, well before the Himalayas existed. They were laid down by rivers and lakes in structural troughs on the stable Peninsular shield, distinguishing them from the marine sedimentary systems found elsewhere.

Distribution: Gondwana rocks occur mainly along the Damodar valley (Jharkhand-West Bengal, the richest belt: Raniganj, Jharia, Bokaro coalfields), the Son-Mahanadi valley (Chhattisgarh-Odisha, e.g., Talcher), the Godavari valley (Telangana-Maharashtra, e.g., Singareni), and smaller basins in the Narmada valley and parts of the northeast.

Economic significance: Gondwana rocks host over 98% of India''s coal reserves, making them the backbone of India''s thermal power generation and steel/coking-coal industry. The Damodar valley coalfields in particular underpin the Chota Nagpur industrial belt''s iron-steel-power complex (linked to Ramagundam, Bokaro, Durgapur). Associated strata also yield fireclay and some iron ore, and the fossil record within Gondwana rocks (notably Glossopteris flora) provides crucial evidence for continental drift/Gondwanaland reconstruction, giving the system additional scientific significance beyond its economic role.', 'Candidates must name specific basins/coalfields (Damodar-Raniganj/Jharia, Son-Mahanadi-Talcher, Godavari-Singareni) rather than a generic ''Gondwana has coal'' statement, and should mention the Glossopteris/continental-drift evidentiary link for extra depth.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q1(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('d55fc855-a2e1-42f2-9fed-721f2f668c98', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 3, 'A', '1(c)', 10, 150, 'Examine the role of Indian Earth Observation Satellite Technology in enhancing weather forecasting and disaster management.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('d55fc855-a2e1-42f2-9fed-721f2f668c98', 'India''s Earth Observation programme, led by ISRO, spans dedicated meteorological satellites (the INSAT/Kalpana series, and the newer INSAT-3D/3DR/3DS series) and remote-sensing satellites (RISAT, Cartosat, Oceansat, Resourcesat) that together support both weather forecasting and disaster management.

Weather forecasting: INSAT-3D/3DR provide continuous imagery of cloud cover, sea-surface temperature, humidity and atmospheric soundings, feeding numerical weather prediction models run by the India Meteorological Department, improving cyclone track/intensity forecasting, monsoon monitoring, and short-range nowcasting of severe convective weather. Scatterometer data from Oceansat improves ocean-surface wind estimation, critical for cyclone genesis tracking in the Bay of Bengal/Arabian Sea.

Disaster management: RISAT''s all-weather, day-night Synthetic Aperture Radar enables flood-extent mapping even through cloud cover (vital during monsoon flooding), landslide and land-subsidence monitoring, and post-disaster damage assessment. Cartosat''s high-resolution imagery supports pre-disaster vulnerability mapping and post-disaster infrastructure damage assessment. The National Disaster Management Authority and state disaster agencies use this satellite data (via NRSC/Bhuvan platforms) for early-warning dissemination (notably for cyclones such as Fani and Amphan, where accurate tracking substantially reduced casualties) and coordinated relief-resource allocation, demonstrating the growing centrality of India''s indigenous space capability to disaster resilience.', 'Naming specific satellites (INSAT-3D, RISAT, Oceansat scatterometer) and a concrete outcome (e.g., improved cyclone-casualty reduction, such as Cyclone Fani''s low death toll attributed partly to accurate satellite-based forecasting) elevates the answer beyond generic ''satellites help disaster management'' statements.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q1(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b3f13d7c-055b-4b7e-a8cb-c442490695fd', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 4, 'A', '1(d)', 10, 150, 'Discuss the impact of the National Green Tribunal Act, 2010 on forest conservation in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b3f13d7c-055b-4b7e-a8cb-c442490695fd', 'The National Green Tribunal (NGT) Act, 2010 established a specialised judicial body with the power to adjudicate environmental disputes efficiently, including matters relating to the enforcement of forest-related legal rights, with the authority to grant relief, compensation, and impose penalties, functioning outside the slower ordinary civil court process.

Impact on forest conservation: The NGT has delivered significant interventions -- halting or modifying infrastructure and mining projects found to violate forest clearance conditions, enforcing compensatory afforestation obligations under the Compensatory Afforestation Fund framework, and ordering closure or penalty for illegal encroachment and diversion of forest land for non-forest use. It has been active in cases concerning the Western Ghats'' Eco-Sensitive Zones, wetland and riverine forest protection, and enforcing Environmental Impact Assessment compliance before project clearance. By providing an accessible, faster forum, the NGT has enabled citizens, NGOs and local communities to challenge forest-diversion decisions that might otherwise proceed unchallenged.

However, limitations persist: NGT orders face implementation and enforcement gaps at the state-government/forest-department level, its jurisdiction has been narrowed by subsequent Supreme Court rulings on certain matters, and under-resourcing (vacancies, regional bench shortages) has slowed case disposal -- meaning the Act has strengthened the legal architecture for forest conservation but has not eliminated on-ground enforcement challenges.', 'Balanced answers should cover both positive interventions (case examples, Western Ghats/CAF enforcement) and genuine implementation limitations, rather than presenting the NGT as an unqualified success -- examiners reward this critical balance.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q1(d). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('e6a4785b-9bdd-4f06-87f1-b656f5a3aca3', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 5, 'A', '2(a)', 20, 350, 'Examine the environmental challenges caused by the solid waste in metropolitan regions of India and discuss the efforts to overcome it.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('e6a4785b-9bdd-4f06-87f1-b656f5a3aca3', 'Introduction: Rapid urbanisation has made municipal solid waste (MSW) one of India''s most pressing metropolitan environmental challenges, with major cities generating waste volumes that routinely outstrip existing collection, treatment and disposal capacity.

Environmental challenges: (i) Landfill overload and leachate contamination -- most metros rely on unscientific open dumpsites (e.g., Delhi''s Ghazipur, Bhalswa and Okhla landfills, some exceeding permissible height and periodically catching fire), which contaminate groundwater and soil through leachate and emit methane, a potent greenhouse gas, alongside frequent landfill fires releasing toxic smoke. (ii) Air pollution from open burning of waste, a major contributor to urban particulate-matter levels, especially in winter inversion conditions. (iii) Water-body pollution from unsegregated waste and plastic entering drains and rivers, worsening urban flooding by blocking stormwater channels (a recurring factor in Mumbai and Chennai flood events) and degrading river water quality (visible along stretches of the Yamuna in Delhi). (iv) Health hazards for waste-pickers and nearby informal settlements from exposure to hazardous/biomedical waste improperly mixed with general MSW. (v) Loss of urban land and biodiversity as expanding dumpsites consume open/wetland space, and (vi) micro-plastic and e-waste accumulation, an emerging and poorly regulated hazard stream.

Efforts to overcome it: Policy-wise, the Solid Waste Management Rules, 2016 mandate source segregation (wet/dry/hazardous), decentralised processing, and extended producer responsibility for packaging waste. The Swachh Bharat Mission (Urban) has driven infrastructure investment in door-to-door collection, material recovery facilities, and waste-to-energy/compost plants across metros. Several cities have adopted bioremediation/biomining of legacy dumpsites (a technique used at Delhi''s landfills and elsewhere to reclaim land and reduce dumpsite volume). Waste-to-energy plants (e.g., in Delhi) convert a share of MSW to power, though air-emission concerns from incineration remain contested. Decentralised composting and community-level segregation initiatives (notably successful models in Indore, repeatedly ranked India''s cleanest city, and Bengaluru''s ward-level composting drives) show that citizen-participation-based decentralised processing can outperform purely centralised end-of-pipe solutions. Extended Producer Responsibility rules for plastic packaging and a phased single-use-plastics ban are additional recent regulatory tools.

Conclusion: While policy architecture has matured considerably since 2016, success remains uneven across metros -- cities with strong municipal governance and citizen participation (Indore) show what is achievable, while others continue to struggle with legacy dumpsite backlogs, underscoring that governance capacity, not just policy design, is the binding constraint.', 'Strong answers name specific real cases (Ghazipur/Bhalswa landfill fires, Indore''s segregation model, Swachh Bharat Mission-Urban, SWM Rules 2016) rather than generic statements about ''waste problems.'' Both halves of the question -- challenges AND efforts/solutions -- must receive comparable depth; many candidates over-invest in describing the problem and under-develop the solutions half.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q2(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('9297d1d1-513c-4337-8502-0ca97142fc19', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 6, 'A', '2(b)', 15, 250, 'Why are millets considered as ''nutri-cereals'' and climate-resilient? Discuss the constraints and opportunities of millet cultivation in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('9297d1d1-513c-4337-8502-0ca97142fc19', 'Millets (jowar, bajra, ragi, and ''minor millets'' like foxtail, kodo, little and barnyard millet) are officially classified by the Government of India as ''Nutri-Cereals'' (2018) because they are exceptionally rich in protein, dietary fibre, iron, calcium (notably ragi), zinc and B-vitamins compared to fine cereals like rice and wheat, and have a lower glycemic index, making them valuable for combating both undernutrition/anaemia and lifestyle diseases like diabetes.

They are climate-resilient because they are C4 photosynthetic plants adapted to hot, dry conditions -- requiring far less water than rice/wheat (bajra needs roughly a quarter of rice''s water footprint), tolerating poor, marginal and degraded soils, thriving in low and erratic rainfall zones, having short growing cycles (60-100 days) that fit multiple cropping and drought-escape strategies, and showing greater resistance to pest/disease pressure and heat stress than conventional cereals -- properties increasingly valuable as climate variability intensifies.

Constraints on cultivation: Declining area under millets over decades due to Green Revolution-era policy bias toward rice/wheat (assured MSP procurement, irrigation subsidy, public distribution system dominance), lower per-hectare yields compared to fine cereals, limited processing/value-addition infrastructure (dehulling, milling) raising consumer-end costs, weak organised market linkages and price realisation for farmers, and low urban consumer awareness/demand historically.

Opportunities: The International Year of Millets (2023, championed by India at the UN) and the National Millets Mission have renewed policy focus, including MSP support, procurement expansion, and inclusion in PDS/school-meal schemes. Growing health-consciousness and export demand (millet-based snacks, breakfast cereals) offer value-addition and branding opportunities (''Shree Anna'' branding). Millets'' low input requirements also align with sustainable/climate-smart agriculture goals, positioning them as a strategic crop for water-stressed and rain-fed regions such as Rajasthan, Maharashtra and Karnataka.', 'The C4 photosynthesis and low water-footprint points are the technical core of ''climate resilience'' and should be explained, not just asserted. Both constraints and opportunities must be addressed with roughly equal depth, and referencing the 2023 International Year of Millets/National Millets Mission shows current-affairs awareness expected at this level.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q2(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('5f19a072-d272-4deb-b5c0-f31d0727a069', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 7, 'A', '2(c)', 15, 250, 'Examine the geostrategic significance of Indian islands.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('5f19a072-d272-4deb-b5c0-f31d0727a069', 'India''s two major island groups -- the Andaman and Nicobar Islands (Bay of Bengal) and Lakshadweep (Arabian Sea) -- hold outsized geostrategic significance disproportionate to their land area, due to their location astride critical Indian Ocean sea lanes.

Andaman and Nicobar Islands: Positioned near the Strait of Malacca -- through which a large share of global trade and energy shipments to East Asia transit -- they give India a forward surveillance and power-projection base overlooking one of the world''s most important choke points. They host India''s only tri-service theatre command (Andaman and Nicobar Command), enabling maritime domain awareness, anti-piracy operations, and rapid response capability across the eastern Indian Ocean. Their proximity to Southeast Asia supports India''s Act East Policy and defence cooperation with partners such as the US, Japan, Australia and ASEAN states (relevant to Quad-related maritime security cooperation), while also serving as a check on the growing presence of other naval powers in the Indian Ocean Region.

Lakshadweep: Located in the Arabian Sea along key western Indian Ocean shipping routes (Gulf-Europe-East Africa trade), Lakshadweep enhances India''s surveillance of its western maritime approaches and Exclusive Economic Zone, supports anti-piracy and counter-smuggling operations, and has seen recent infrastructure and connectivity investment partly framed in strategic-plus-tourism terms.

Broader significance: Both island groups extend India''s Exclusive Economic Zone substantially, providing access to fisheries and potential seabed mineral resources, and function as forward bases for maritime domain awareness (radar/surveillance networks) critical to India''s broader Indo-Pacific strategy and its role as a net security provider in the Indian Ocean Region.', 'Both island groups must be addressed, each tied to a specific strategic function (Malacca Strait chokepoint oversight for A&N, western Arabian Sea route oversight for Lakshadweep) rather than treated as a single undifferentiated ''islands are strategic'' statement. Mentioning the tri-service Andaman and Nicobar Command by name is a strong specific detail examiners look for.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q2(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('47c696a2-9cbf-4067-a059-1f40d6834cd4', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 8, 'A', '3(a)', 20, 350, 'Indian Pharma Industry has to move from ''volume'' to ''value'' leadership to capture global market. Discuss.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('47c696a2-9cbf-4067-a059-1f40d6834cd4', 'Introduction: India is the world''s largest supplier of generic medicines by volume (~20% of global generic exports) and a major vaccine producer, often called the ''pharmacy of the world.'' Yet its global market-value share remains modest relative to its volume share, since Indian exports concentrate in low-margin generic formulations rather than high-value patented/complex products.

The volume-based model: India''s pharma success has historically rested on cost-competitive manufacturing of off-patent generic drugs and active pharmaceutical ingredients (APIs), leveraging skilled low-cost labour, reverse-engineering capability, and a strong domestic chemical/process-engineering base -- but this model faces intensifying price competition from other low-cost producers and thinning margins, while dependence on imported APIs (particularly from China for key starting materials) exposes the sector to supply-chain vulnerability, as the COVID-19 pandemic exposed.

Why value leadership is necessary: (i) Margin sustainability -- generic-volume competition is a race to the bottom on price; higher-value segments (biosimilars, complex generics, specialty formulations, novel drug delivery systems) command better margins. (ii) Reducing import dependence -- domestic API/bulk-drug manufacturing investment (supported by the Production-Linked Incentive scheme for bulk drugs and API parks) reduces strategic vulnerability and captures more value domestically rather than importing intermediates. (iii) R&D and innovation -- shifting toward novel drug discovery, biologics, and biosimilars (India already has notable biosimilar export success) requires sustained R&D investment, currently far below that of US/EU/Japanese pharma majors as a share of revenue. (iv) Regulatory and quality upgrades -- achieving and maintaining USFDA/EMA-grade manufacturing quality standards is essential to access premium regulated markets rather than only price-sensitive ones. (v) Branding and IP strategy -- building recognised Indian pharma brands and strategic patent/licensing capability (rather than pure reverse-engineering) is necessary to move up the value chain.

Policy support: The PLI scheme for pharmaceuticals and bulk drugs, three bulk-drug parks, and medical-device parks aim to strengthen the domestic API base; increased public and private R&D funding, and promotion of contract research/manufacturing (CRAMS) partnerships with global majors, are additional levers.

Conclusion: Sustained investment in R&D, quality infrastructure, and strategic API self-reliance -- not volume expansion alone -- is what will allow India to convert its manufacturing scale into genuine global market-value leadership.', 'Strong answers explicitly distinguish ''volume'' (India''s existing strength: generic export share) from ''value'' (margins, biosimilars, IP, branding) and name concrete policy instruments (PLI scheme, bulk-drug parks) rather than making a purely abstract argument. The China-API-dependency vulnerability point is a frequently expected current-affairs anchor.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q3(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('65b424d9-b347-4557-af95-a71785045fc7', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 9, 'A', '3(b)', 15, 250, 'Discuss the problems of floods and their management with special reference to Indo-Gangetic Plain.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('65b424d9-b347-4557-af95-a71785045fc7', 'The Indo-Gangetic Plain, drained by the Ganga, its Himalayan tributaries (Ghaghara, Gandak, Kosi, Son) and the Brahmaputra system further east, is India''s most flood-prone region, accounting for a large share of the country''s annual flood-affected area and damage.

Problems: Heavy, concentrated monsoon rainfall combined with the steep gradient of Himalayan tributaries causes rapid runoff and frequent channel-shifting -- the Kosi river in Bihar is notorious for dramatic course changes (''Sorrow of Bihar''), repeatedly devastating settlements. Siltation from Himalayan erosion raises riverbeds over time, reducing channel capacity and worsening overflow frequency. Embankments (bunds), built to confine rivers, often paradoxically raise flood risk by preventing natural floodplain spreading and increasing breach severity when they do fail. Rapid, unplanned urbanisation and encroachment on floodplains and natural drainage channels (seen in cities like Patna) reduces the land''s natural water-absorption capacity. Upstream deforestation in the Himalayan catchment intensifies runoff and sediment load. Cross-border river-basin coordination challenges (with Nepal, given the Kosi and Gandak headwaters) complicate flood-forecasting and reservoir-management cooperation. Climate change is intensifying extreme rainfall events, increasing flash-flood frequency and severity.

Management approaches: Structural measures include embankments, reservoirs (e.g., proposed high dams on Nepal''s rivers for flood moderation), and channel-training works, though these carry the trade-offs noted above. Non-structural measures increasingly emphasised include flood-forecasting and early-warning systems (Central Water Commission''s flood forecasting network), floodplain zoning regulation to restrict construction in high-risk areas, disaster-resilient infrastructure and housing, community-based flood preparedness, and basin-wide integrated water-resource management involving India-Nepal cooperation on Kosi/Gandak catchment management. A shift from purely structural, embankment-centric approaches toward integrated floodplain and basin management is now recognised as necessary for durable flood risk reduction.', 'Naming the Kosi river''s notorious course-shifting behaviour and India-Nepal cross-border basin cooperation are specific, high-value details for this question; a common weakness is a generic ''floods happen due to heavy rain, managed by dams and embankments'' answer lacking Indo-Gangetic-specific detail.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q3(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('71fe95f3-9f04-48b9-8637-18ec8dc12ee7', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 10, 'A', '3(c)', 15, 250, 'Critically examine the role of petroleum energy resources on International Geopolitics with special reference to India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('71fe95f3-9f04-48b9-8637-18ec8dc12ee7', 'Petroleum has historically been a central driver of international geopolitics -- control over reserves, transit routes and pricing has shaped alliances, conflicts and foreign policy for over a century, from the Middle East''s centrality in global power politics (OPEC''s formation and its 1970s oil-embargo leverage) to more recent tensions around sanctions-driven oil markets (Russia post-2022, Iran).

Global dimension: Petroleum-exporting states derive substantial geopolitical leverage from reserves and production control (OPEC/OPEC+ coordination influencing global prices), while importing powers pursue diversified supply, strategic reserves, and naval presence to secure sea lanes (e.g., the Strait of Hormuz, through which a large share of global oil transits, remains a persistent geopolitical flashpoint). Petro-dollar recycling and energy-based sanctions (against Russia, Iran, Venezuela) demonstrate how petroleum is wielded as both economic and coercive foreign-policy leverage.

India''s specific position: India imports over 85% of its crude oil requirement, making energy security a central foreign-policy priority. This drives diversification strategy -- traditional heavy reliance on Gulf suppliers (Saudi Arabia, Iraq, UAE) balanced by growing imports from Russia (sharply increased post-2022 due to discounted pricing under Western sanctions, a pragmatic but geopolitically sensitive choice balancing economic benefit against relations with Western partners) and engagement with US and African suppliers for diversification. India maintains Strategic Petroleum Reserves for short-term supply-shock buffering, and has pursued equity-oil investments abroad (ONGC Videsh) to secure long-term supply. Petroleum dependence also shapes India''s foreign policy engagement with Gulf states (large expatriate workforce and remittance ties compounding the relationship) and its cautious, interest-based positioning on Middle East and Russia-Ukraine-related geopolitical alignments, prioritising energy security and strategic autonomy over rigid bloc alignment.

Critical assessment: While petroleum dependence gives India''s foreign policy a pragmatic, multi-aligned character, it also exposes the economy to price volatility (import-bill and rupee pressure during price spikes) and remains a structural vulnerability that renewable-energy transition and domestic exploration efforts only partially mitigate in the near term.', 'The ''critically examine'' instruction requires an evaluative angle, not just description -- the answer should flag India''s vulnerability/trade-offs (import-bill exposure, balancing Russia-discount pricing against Western relations) rather than only listing supplier diversification as an unqualified success.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q3(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ee2fd0a1-84e9-4e18-87d3-15c9cb1db6b9', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 11, 'A', '4(a)', 20, 350, 'With falling fertility rate and rising median age, how can India translate demographic dividend to economic dividend?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ee2fd0a1-84e9-4e18-87d3-15c9cb1db6b9', 'Introduction: India''s total fertility rate has fallen below replacement level (around 2.0), and its median age, while still young relative to China and developed economies, is rising -- meaning India''s demographic dividend window (a high working-age-to-dependent ratio) is time-limited and requires active policy conversion into economic dividend before it closes.

Why conversion isn''t automatic: A large working-age population only becomes an economic dividend if it is healthy, skilled, and productively employed; without adequate human-capital investment and job creation, a large youth cohort can instead become a demographic burden (unemployment, social instability) rather than a dividend -- as seen in the current mismatch between rising labour-force entrants and formal-sector job creation.

Policy measures for conversion: (i) Education and skilling -- substantially improving school learning outcomes, expanding vocational training and skill-certification (Skill India Mission) aligned to actual industry/labour-market demand, and increasing higher-education access and quality. (ii) Health investment -- ensuring the workforce is physically and mentally productive through improved public healthcare, nutrition (addressing persistent stunting/anaemia), and maternal-child health, since human capital quality determines productivity, not headcount alone. (iii) Employment generation -- accelerating labour-intensive manufacturing growth (Production-Linked Incentive schemes, ''Make in India''), formalising the informal sector to extend social security and productivity gains, and removing labour-market rigidities that discourage formal hiring. (iv) Female labour-force participation -- India''s female workforce participation remains low by international standards; raising it (through childcare support, safety, and workplace-inclusion policy) would substantially expand the effective working-age contributing population. (v) Regional targeting -- since fertility decline and ageing are occurring unevenly (southern/western states ageing faster than northern/eastern states), a two-track strategy is needed: leveraging still-young northern/eastern state populations for labour supply while addressing ageing-related productivity and social-security needs in the south/west. (vi) Urbanisation and infrastructure -- ensuring cities can absorb rural-to-urban labour migration productively, with adequate housing, transport and services.

Conclusion: India''s dividend window is finite -- UN projections suggest it narrows from around the 2040s-50s as the population itself ages -- making the coming two decades a critical, time-bound opportunity that requires urgent, coordinated investment in health, education, skilling and job creation rather than passive reliance on demographic structure alone.', 'A strong answer must explicitly address the ''why conversion isn''t automatic'' logic (dividend vs burden framing) before listing policy measures, and should incorporate the regional/inter-state demographic-transition variation (south/west ageing faster than north/east) as a sophistication marker, since this is a well-known feature of India''s demography specifically relevant to this question.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q4(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('aff87b22-4e6f-47b0-b323-494e67adda59', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 12, 'A', '4(b)', 15, 250, 'Poor quality of urban planning in India is a huge constraint in realizing the true economic potentials of urbanization. Critically examine.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('aff87b22-4e6f-47b0-b323-494e67adda59', 'Urbanisation is generally associated with productivity gains from agglomeration economies, yet India''s urban centres often fail to fully capture these benefits due to planning deficiencies.

Manifestations of poor planning: Unplanned peripheral sprawl and unauthorised colonies outpace formal Master Plan implementation, producing haphazard land use and fragmented infrastructure provision. Chronic under-investment in urban transport leads to severe congestion, imposing large economic costs (lost productivity, fuel wastage, delayed goods movement) in cities like Bengaluru, Mumbai and Delhi. Inadequate water supply, sewerage and stormwater drainage infrastructure causes recurring urban flooding (Mumbai, Chennai, Bengaluru) and health hazards, damaging both economic activity and quality of life that could otherwise attract investment and skilled labour. Fragmented, multiplicity-of-agency urban governance (multiple parastatals, weak empowerment of Urban Local Bodies despite the 74th Constitutional Amendment) slows coordinated infrastructure delivery and land-use enforcement. Housing shortages and slow formal housing supply push a large share of the urban workforce into informal settlements lacking secure tenure, limiting their ability to invest in or leverage housing assets economically. Weak land-use/zoning enforcement leads to incompatible mixed development (industrial/residential conflicts, encroachment on water bodies/floodplains), raising environmental and disaster risk that deters long-term investment.

Economic consequences: These planning failures raise the effective cost of doing business, reduce urban labour productivity, deter both domestic and foreign investment in urban-based manufacturing/services, and mean Indian cities often fail to achieve the scale economies and innovation spillovers seen in well-planned global urban agglomerations.

Way forward: Strengthening ULB financial and planning autonomy, integrating land-use with transport planning (transit-oriented development), enforcing Master Plans through GIS-based monitoring, and mainstreaming climate/disaster-resilient urban design are essential to convert India''s urbanisation into genuine economic dividend rather than congestion and informality.', '''Critically examine'' requires linking each planning deficiency explicitly to an economic cost (productivity loss, deterred investment, informality) rather than simply cataloguing urban problems; naming the 74th Constitutional Amendment and ULB governance weakness shows institutional depth expected at this level.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q4(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('5ed4d6c3-8595-4468-a44f-14ac44570963', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 13, 'A', '4(c)', 15, 250, 'Highlight the salient features of India''s trade policy. Discuss the status of India''s balance of trade with China.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('5ed4d6c3-8595-4468-a44f-14ac44570963', 'Salient features of India''s trade policy: India''s Foreign Trade Policy framework (most recently the FTP 2023, a shift to an open-ended, dynamically updated policy rather than fixed five-year cycles) emphasises: (i) export promotion through schemes like RoDTEP (Remission of Duties and Taxes on Exported Products) and interest-equalisation support, replacing earlier WTO-inconsistent schemes; (ii) ease of doing business via digitisation of trade documentation and paperless processing; (iii) promotion of districts as export hubs to broaden export participation beyond traditional industrial clusters; (iv) special focus on e-commerce exports and dual-use/strategic-goods export facilitation; (v) a strategic pivot toward Free Trade Agreements with select partners (UAE, Australia, and ongoing negotiations with the EU and UK) rather than broad multilateral liberalisation, reflecting a calibrated, interest-based trade diplomacy; and (vi) import policy calibration -- tariff protection for select domestic manufacturing sectors (aligned with ''Atmanirbhar Bharat''/PLI schemes) alongside targeted liberalisation for inputs needed by export industries.

Balance of trade with China: India runs a large and persistent trade deficit with China, its largest bilateral merchandise trade deficit with any country, driven by heavy dependence on Chinese imports of electronics/telecom equipment, machinery, active pharmaceutical ingredient intermediates, and industrial inputs, while Indian exports to China (ores, cotton, organic chemicals) remain comparatively limited and volatile. This deficit has widened over the past decade despite periodic bilateral political tensions (post-Galwan border clashes), reflecting India''s continued structural dependence on Chinese manufacturing inputs even as diplomatic relations remain strained -- a tension the government has sought to address through import-substitution measures (PLI schemes in electronics, APIs, solar equipment) and scrutiny of Chinese investment, though near-term structural dependence remains significant given the depth of existing supply-chain integration.', 'The China trade-deficit discussion should note the apparent paradox of a large and growing deficit persisting despite political/border tensions -- this tension is exactly what distinguishes a sophisticated answer from a purely descriptive statistic-recitation one. Mentioning specific policy instruments (RoDTEP, FTP 2023, PLI) for the first part avoids a vague, unsupported description of ''trade policy.''', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section A, Q4(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b0c4e2cd-87ec-4dec-83ef-ee22b4f87c7d', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 14, 'B', '5(a)', 10, 150, 'Identify the jute-producing areas in India and discuss the major causes of decline of jute mill industry in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b0c4e2cd-87ec-4dec-83ef-ee22b4f87c7d', 'Jute cultivation in India is concentrated overwhelmingly in the Ganga-Brahmaputra deltaic tract, where high humidity, heavy rainfall (150-250 cm), high temperature, and fertile alluvial soil with good water retention provide ideal conditions. West Bengal is by far the largest producer (deltaic districts such as Nadia, Murshidabad, Malda, North & South 24 Parganas), followed by Bihar, Assam, and Odisha, with the Hooghly riverbanks historically forming the core of the associated jute-milling belt (Kolkata/Howrah region).

Causes of decline of the jute mill industry: Competition from cheaper synthetic substitutes (polypropylene/plastic packaging) has steadily eroded jute''s traditional packaging-material market. Ageing, technologically outdated mills (many dating to the colonial era) have failed to modernise, raising costs and reducing competitiveness against synthetic alternatives and other jute-exporting nations (notably Bangladesh). Labour unrest, frequent mill closures/lockouts, and financial stress among jute companies have caused chronic underutilisation of capacity. Shrinking export demand, as global buyers shifted to synthetic packaging, further weakened the industry, despite government support measures such as the Jute Packaging Materials Act mandating jute use for foodgrain/sugar packaging, which has only partially offset the structural decline.', 'Candidates should name specific West Bengal deltaic districts, not just ''West Bengal,'' and should identify at least three distinct causes of decline (synthetic competition, mill obsolescence, labour/financial stress) rather than a single generic reason.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q5(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('ad354d81-b219-426b-ac8a-ad3a0d32c7f0', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 15, 'B', '5(b)', 10, 150, 'Urban built environment in big cities of India creates key changes in biophysical character of the landscape. Discuss.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('ad354d81-b219-426b-ac8a-ad3a0d32c7f0', 'The urban built environment -- concrete, asphalt, buildings and reduced vegetation cover -- systematically alters the biophysical landscape of India''s large cities in several measurable ways. The Urban Heat Island effect raises city-centre temperatures several degrees above surrounding rural areas due to heat-absorbing impervious surfaces and reduced evapotranspiration from lost green cover, clearly documented in cities like Delhi and Ahmedabad. Hydrology is altered as impervious surfaces (roads, rooftops, paved areas) drastically reduce natural infiltration, increasing surface runoff volume and speed -- a major contributor to urban flash-flooding in Mumbai, Chennai and Bengaluru, especially where natural drainage channels and wetlands have been encroached upon or built over. Loss of urban wetlands, lakes and green cover (Bengaluru''s shrinking lake system is a well-documented case) reduces natural water storage/recharge capacity and urban biodiversity habitat. Air quality is degraded through concentrated vehicular/industrial emissions trapped by altered urban wind and thermal patterns. Soil compaction and sealing beneath built infrastructure disrupts groundwater recharge, contributing to falling water tables in rapidly urbanised zones despite higher overall water demand.', 'The Urban Heat Island effect and altered hydrology/runoff are the two changes examiners most expect to see explained mechanistically (not just named); a specific Indian city example for each (Bengaluru lakes, Chennai/Mumbai flooding) substantially strengthens the answer.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q5(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('3b2e7c80-b1a2-4e2f-b79c-ee18f3535096', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 16, 'B', '5(c)', 10, 150, 'Explain the geological characteristics and ecological significance of the Eastern Ghats.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('3b2e7c80-b1a2-4e2f-b79c-ee18f3535096', 'The Eastern Ghats are a discontinuous, highly eroded range of ancient Precambrian metamorphic rocks (khondalites, charnockites, gneisses) running roughly parallel to India''s east coast from Odisha to Tamil Nadu, geologically far older and more heavily denuded than the younger, more continuous Western Ghats -- their broken, discontinuous character results from prolonged erosion by east-flowing peninsular rivers (Mahanadi, Godavari, Krishna, Kaveri) which have cut wide gaps through the range on their way to the Bay of Bengal, unlike the Western Ghats'' continuous escarpment.

Ecological significance: Despite lower average elevation and rainfall than the Western Ghats, the Eastern Ghats harbour significant dry and moist deciduous forest biodiversity, including several wildlife sanctuaries and tiger reserves (e.g., in the Eastern Ghats'' Andhra Pradesh-Odisha stretches). They form an important watershed for peninsular rivers feeding the Bay of Bengal, support tribal communities dependent on forest resources, and their mineral-rich rock base (bauxite, iron ore) makes them ecologically sensitive zones where mining pressure often conflicts directly with forest and tribal-livelihood conservation.', 'The key geological point examiners check for is the discontinuity/older-and-more-eroded-than-Western-Ghats characteristic, explained via peninsular river gap-cutting, rather than simply describing the range as a mirror of the Western Ghats. Mentioning mining-versus-conservation tension adds contemporary relevance.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q5(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('1f85fd01-bb67-473a-beae-b6e076e209e8', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 17, 'B', '5(d)', 10, 150, 'Explain the cultural regions of India based on their cultural attributes.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('1f85fd01-bb67-473a-beae-b6e076e209e8', 'India''s cultural regionalisation, following geographers like O.H.K. Spate and later regional-culture scholars, is typically based on attributes such as language, religion, dominant social customs, dress, cuisine, architecture, and historical-political heritage rather than purely physical boundaries.

Broad cultural regions include: North India (Indo-Gangetic Hindi-Urdu belt, wheat-based cuisine, historically shaped by successive Indo-Aryan and Indo-Islamic influences); Northeast India (culturally and linguistically distinct Tibeto-Burman-influenced tribal societies with strong community/clan-based social organisation, distinct from mainland Hindu-caste social structure); East India (Bengali/Odia cultural zone, strong literary-artistic tradition, rice-fish cuisine); West India (Gujarati-Marathi commercial/mercantile cultural tradition, Jain-Hindu religious mix); Central India (tribal-dominated cultural zone, e.g., Gond and other Adivasi traditions); South India (Dravidian-language cultural zone -- Tamil, Telugu, Kannada, Malayalam -- distinct temple-architecture tradition, rice-based cuisine, historically less influenced by Indo-Islamic rule than the north); and the Himalayan cultural zone (Buddhist-influenced, high-altitude pastoral/agrarian communities in Ladakh, Sikkim, and parts of Himachal/Uttarakhand). These regions are not rigidly bounded but represent gradational cultural attribute clusters shaped by historical migration, religion, and physical-environmental adaptation.', 'Answers should explicitly name the basis of regionalisation (language, religion, custom, historical influence) rather than merely listing regions geographically; acknowledging that boundaries are gradational/fuzzy rather than sharp is a mark of sophistication.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q5(d). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('38ce3b26-40b2-473a-93ef-8151b2a12b71', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 18, 'B', '5(e)', 10, 150, 'Why are critical minerals essential for the economic development and national security in India?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('38ce3b26-40b2-473a-93ef-8151b2a12b71', 'Critical minerals -- such as lithium, cobalt, nickel, rare earth elements, graphite and copper -- are those with high economic importance and significant supply-risk due to concentrated global production (often dominated by a small number of countries, notably China for rare earths and processing capacity).

Economic development significance: These minerals are indispensable inputs for strategic emerging industries -- lithium-ion batteries for electric vehicles and grid storage, rare earths for permanent magnets used in wind turbines and EV motors, semiconductors, and renewable-energy equipment -- placing them at the centre of India''s clean-energy transition and manufacturing ambitions (PLI schemes for batteries/EVs, semiconductor fabrication). Domestic availability or secure supply chains directly determine India''s ability to capture value in these high-growth future industries rather than remaining import-dependent.

National security significance: Critical minerals are essential for defence applications (advanced alloys, electronics, precision-guided systems) and for maintaining supply-chain resilience against geopolitical coercion, given that a handful of countries (especially China) dominate global processing capacity even where raw ore is more widely distributed. India''s 2023 identification of 30 critical minerals, the newly established Khanij Bidesh India Ltd for overseas mineral asset acquisition, and auction of domestic critical-mineral blocks (including lithium finds in Jammu and Kashmir) reflect a strategic push to reduce import dependence and secure both economic and security interests simultaneously.', 'Naming India''s 2023 critical-minerals list and the J&K lithium discovery/KABIL initiative demonstrates current-affairs grounding expected for this kind of applied-economic-geography question; a generic answer about minerals ''being important'' without these specifics under-performs.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q5(e). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('6a1d7035-f5e4-40d4-bbf6-4e8006e7b57c', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 19, 'B', '6(a)', 20, 350, 'A large number of Indian cities have complex morphological characteristics due to their historical evolution. Elucidate.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('6a1d7035-f5e4-40d4-bbf6-4e8006e7b57c', 'Introduction: Urban morphology -- the physical form, street pattern, land-use arrangement and building fabric of a city -- in India frequently reflects layered historical development rather than planned, uniform design, producing complex, often contradictory spatial patterns within a single city.

Pre-colonial cores: Many Indian cities retain a historic core with organic, narrow, winding street patterns clustered around a religious, royal or trading nucleus (e.g., the walled city of Old Delhi around the Red Fort/Jama Masjid, the old city of Jaipur with its distinctive planned grid reflecting Vastu-based Rajput town planning, or Varanasi''s dense riverside ghats-oriented core) -- these zones typically show high building density, mixed residential-commercial use, and street patterns unsuited to modern vehicular traffic.

Colonial-era additions: British-era ''civil lines'' and cantonment areas were deliberately planned with wide, tree-lined avenues, low-density bungalow housing, and segregated administrative/military zones (e.g., New Delhi''s Lutyens'' zone, Bengaluru''s Cantonment area, Pune''s Camp area) -- producing a sharp morphological contrast with the adjoining older ''native town'' areas, a duality still visible in many Indian cities today.

Post-independence planned extensions: Government-planned townships and satellite developments (Chandigarh''s Corbusier-designed sectoral grid, Bhubaneswar''s early planned layout, and various state capital/industrial townships) introduced a third morphological layer -- rationalised zoning, wide roads, and functional segregation, contrasting sharply with both the pre-colonial core and colonial cantonment patterns.

Post-liberalisation/contemporary sprawl: Since the 1990s, rapid economic growth has driven unplanned peripheral expansion -- IT-corridor development (Bengaluru''s Whitefield/Electronics City, Gurugram''s private-sector-led high-rise/commercial sprawl), often growing faster than formal planning and infrastructure can absorb, producing a fourth, frequently poorly integrated morphological layer.

Resulting complexity: A single large Indian city (Delhi is the clearest example) can therefore contain, within a short distance, a dense pre-colonial walled core, colonial-era low-density civil lines, planned post-independence government colonies, and unplanned contemporary peripheral sprawl -- each with distinct street patterns, building density, and infrastructure standards, making integrated city-wide planning, transport design and service delivery exceptionally difficult, and explaining much of the fragmented governance and infrastructure-mismatch problems seen in Indian urban management today.

Conclusion: Indian urban morphology is thus best read as a historical palimpsest -- successive eras of development overlaid rather than replaced -- and understanding this layered evolution is essential to designing planning interventions appropriate to each zone''s distinct morphological character.', 'The strongest answers use the ''palimpsest''/layered-history framing explicitly and name concrete examples for each historical layer (pre-colonial core, colonial cantonment, post-independence planned town, contemporary sprawl) rather than discussing morphology in the abstract. Delhi is the most efficient single-city example to illustrate all four layers at once.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q6(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('7cc65534-07b7-4231-b2e4-5481737e66e3', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 20, 'B', '6(b)', 15, 250, 'Discuss the significance of organic farming for sustainable agricultural development in India.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('7cc65534-07b7-4231-b2e4-5481737e66e3', 'Organic farming -- cultivation without synthetic fertilisers, pesticides or GM inputs, relying instead on biological inputs (compost, biofertilisers, crop rotation, biological pest control) -- holds significance for sustainable agricultural development in India along several dimensions.

Environmental significance: Organic practices reduce soil degradation and improve long-term soil health (organic matter content, microbial activity, water-holding capacity), reversing damage from decades of intensive chemical-input Green Revolution agriculture in regions like Punjab-Haryana where soil health and groundwater have visibly deteriorated. It reduces agro-chemical runoff into water bodies (mitigating eutrophication) and lowers the carbon/energy footprint associated with synthetic fertiliser production.

Economic significance: Organic produce commands premium prices in domestic and export markets (India is a leading global exporter of organic products, notably from Madhya Pradesh, Sikkim -- India''s first fully organic state -- and parts of the Northeast), offering smallholder farmers a potential value-addition pathway, though certification costs and yield transition risk (often lower yields in early conversion years) remain real constraints.

Social/health significance: Reduced pesticide residue benefits both farmer health (lower chemical exposure) and consumer health, addressing rising food-safety concerns; organic farming''s typically higher labour intensity can also support rural employment.

Sustainability trade-offs: Organic farming alone cannot easily match Green Revolution-era yield levels needed for national food security at current population scale, meaning it is best positioned as a complementary strategy -- suited to specific regions, crops (horticulture, spices, tea) and farmer segments -- alongside broader sustainable-intensification approaches (natural farming, integrated nutrient management) rather than a wholesale replacement for conventional agriculture nationwide. India''s Paramparagat Krishi Vikas Yojana and Sikkim''s full-state organic conversion are instructive policy models for scaling organic adoption where locally appropriate.', 'A balanced answer should acknowledge organic farming''s yield/scale limitations alongside its genuine environmental and market-premium benefits -- an uncritically positive answer misses the ''critically examine sustainability'' nuance a top-scoring response typically includes. Citing Sikkim and PKVY by name shows applied policy knowledge.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q6(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b77ac2fc-4bed-4177-9755-171e8014dacc', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 21, 'B', '6(c)', 15, 250, 'Examine the geopolitical impact of bilateral relationship between India and Sri Lanka.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b77ac2fc-4bed-4177-9755-171e8014dacc', 'India-Sri Lanka relations are shaped by deep geographic proximity (separated only by the Palk Strait), historical-cultural-religious ties (Buddhism, Tamil ethnic linkages), and India''s core strategic interest in preventing hostile external power presence in an island located directly astride major Indian Ocean shipping lanes just off India''s southern coast.

Economic dimension: India is among Sri Lanka''s largest trading partners and a major source of investment and development assistance; India''s decisive support during Sri Lanka''s 2022 economic/debt crisis (extending several billion dollars in credit lines, fuel, food and currency-swap support) significantly reinforced bilateral goodwill and demonstrated India''s role as first-responder neighbour (''Neighbourhood First'' policy in action).

Strategic/geopolitical dimension: India''s central concern is countering the expanding footprint of China in Sri Lanka -- notably Chinese-funded infrastructure projects (Hambantota Port, taken on a 99-year lease by China after Sri Lanka''s debt distress, and Colombo Port City) which India views as strategically significant ''String of Pearls''-type developments potentially enabling Chinese naval access near Indian waters. India has responded by expanding its own connectivity, energy and port-development cooperation (e.g., involvement in Trincomalee-related energy infrastructure and the Colombo/Kankesanthurai port projects) to balance Chinese influence through its own economic engagement rather than confrontation.

Ethnic/domestic dimension: The Tamil ethnic question in Sri Lanka (relating to the Sri Lankan Tamil minority, post-civil-war reconciliation, and implementation of the 13th Amendment''s devolution provisions) remains a sensitive factor in bilateral relations, given domestic political pressure from Tamil Nadu on the Indian government to advocate for Tamil rights and devolution.

Overall, the relationship illustrates how India balances economic-humanitarian goodwill, strategic competition with China, and domestic ethnic-politics sensitivity within a single, geographically proximate bilateral relationship.', 'The China-Hambantota/String-of-Pearls angle and the 2022 Sri Lankan economic-crisis assistance are the two most current, high-value specifics examiners expect; the Tamil-ethnic/13th-Amendment dimension adds necessary domestic-political nuance often left out of purely strategic-geopolitics-focused answers.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q6(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('e8a6b272-16c3-4963-a87f-b7caa48d5eef', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 22, 'B', '7(a)', 20, 350, 'Discuss the green energy initiatives of India as a signatory nation to the Paris Agreement.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('e8a6b272-16c3-4963-a87f-b7caa48d5eef', 'Introduction: As a Paris Agreement signatory, India has committed to Nationally Determined Contributions (NDCs) that include reducing emissions intensity of GDP by 45% (from 2005 levels) by 2030, achieving about 50% cumulative electric power installed capacity from non-fossil sources by 2030, and reaching net-zero emissions by 2070 -- driving a wide-ranging set of green-energy initiatives.

Renewable capacity expansion: India has rapidly scaled solar and wind capacity, becoming one of the world''s largest renewable-energy markets, through initiatives like the National Solar Mission (part of the National Action Plan on Climate Change), large-scale solar parks (e.g., Bhadla in Rajasthan, among the world''s largest), and offshore/onshore wind expansion, alongside the ambitious International Solar Alliance, an India-led global coalition promoting solar deployment particularly among developing/sunshine-rich nations.

Green hydrogen and emerging fuels: The National Green Hydrogen Mission aims to position India as a global green-hydrogen production and export hub, targeting significant production capacity to decarbonise hard-to-abate sectors (steel, fertiliser, refining) and shipping fuel.

Electric mobility: The FAME (Faster Adoption and Manufacturing of Electric Vehicles) scheme and PLI incentives for battery/EV manufacturing aim to accelerate transport-sector decarbonisation, alongside expanding charging infrastructure.

Energy efficiency and grid integration: The PAT (Perform, Achieve, Trade) scheme drives industrial energy efficiency; the Green Energy Corridor project strengthens transmission infrastructure needed to integrate variable renewable generation into the national grid; and rooftop solar schemes (PM Surya Ghar) aim to expand distributed generation.

International leadership initiatives: Beyond domestic action, India has championed global coalitions such as the International Solar Alliance and the Coalition for Disaster Resilient Infrastructure, positioning itself as a leader among developing nations balancing climate ambition with development needs, and has consistently argued for climate finance and technology-transfer support from developed nations under the principle of Common But Differentiated Responsibilities.

Challenges: Despite this progress, India''s continued reliance on coal for grid stability and base-load power (given intermittency challenges of renewables), land-acquisition and transmission bottlenecks for large renewable projects, and the scale of financing required to meet 2030 targets remain significant implementation challenges.

Conclusion: India''s green-energy programme reflects a genuine, wide-ranging policy commitment consistent with its Paris Agreement obligations, though the pace of coal phase-down and financing mobilisation will determine whether stated targets are fully achieved on schedule.', 'Naming specific programmes (National Green Hydrogen Mission, International Solar Alliance, FAME, PM Surya Ghar) with their specific purpose, rather than a vague ''India is going green'' narrative, is what distinguishes a strong 20-mark answer; acknowledging implementation challenges (coal dependence, financing) shows the balanced, critical perspective examiners reward over unqualified praise.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q7(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('fdc440be-41cf-417e-8ee7-22be40773c4a', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 23, 'B', '7(b)', 15, 250, 'India''s poultry sector has become one of the fastest growing areas of the country''s agricultural sector. Examine its opportunities and challenges.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('fdc440be-41cf-417e-8ee7-22be40773c4a', 'India''s poultry sector -- broiler (meat) and layer (egg) production -- has grown at a rapid pace over recent decades, making India among the world''s largest egg and broiler-meat producers, driven by rising incomes, urbanisation, and dietary diversification toward animal protein.

Opportunities: Rising domestic demand for affordable animal protein offers sustained growth potential, particularly as incomes rise across urban and semi-urban India. The sector offers relatively quick investment-return cycles (broiler cycles of just 5-6 weeks) compared to other livestock, making it attractive for smallholder and landless rural households as a livelihood diversification option, with significant employment generation across the value chain (feed, hatcheries, processing, transport, retail). Integration models (contract farming with large integrators providing chicks, feed and technical support) have improved productivity and market access for small producers. Export potential exists for poultry genetics, feed ingredients, and processed/value-added poultry products to neighbouring and Gulf markets, alongside domestic potential for organised retail and cold-chain-based value addition.

Challenges: The sector is highly vulnerable to feed-price volatility (maize and soybean meal price swings directly affect profitability), given feed constitutes the majority of production cost. Disease outbreaks, notably periodic Avian Influenza (bird flu) incidents, cause major economic losses and consumer-demand shocks, and biosecurity standards remain inconsistent, especially among small/backyard producers. Climate stress (heat waves affecting bird mortality and productivity) is an emerging concern. Market volatility and price crashes during oversupply periods hurt small producers lacking integrator/contract protection. Cold-chain and processing infrastructure remains underdeveloped relative to production growth, limiting value addition and export competitiveness, while informal/unorganised segments of the sector face weak access to credit, insurance, and veterinary services.

Overall, the sector''s opportunities are substantial given demand trends, but realising its full potential requires addressing feed-cost volatility, biosecurity/disease management, and infrastructure gaps.', 'Both halves (opportunities and challenges) require comparable depth; the feed-cost-volatility and avian-influenza-disease points are the two most specific, exam-relevant challenges examiners expect to see named rather than a generic ''faces various challenges'' statement.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q7(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c704289a-8569-4c83-95b2-96ba5139ef26', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 24, 'B', '7(c)', 15, 250, 'Critically examine the ecological and economic impact of Indira Gandhi Canal Command Area development.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c704289a-8569-4c83-95b2-96ba5139ef26', 'The Indira Gandhi Canal (formerly Rajasthan Canal), India''s longest canal, brings Sutlej-Beas waters into the arid/semi-arid tracts of northwestern Rajasthan (Ganganagar, Hanumangarh, Bikaner, Jaisalmer districts), transforming a substantial command area of what was largely desert land.

Economic impact: The canal has enabled significant agricultural transformation -- converting arid rangeland into productive irrigated cropland growing wheat, cotton, mustard and, notably, water-intensive crops like paddy and sugarcane in some stretches -- boosting regional agricultural output, farm incomes, and supporting allied activities like dairy farming through improved fodder availability. It has also enabled settlement and population growth in a previously sparsely inhabited desert margin, supporting rural livelihoods and reducing distress migration from the command area.

Ecological impact -- and critical concerns: Despite these gains, the project has generated serious ecological problems. Over-irrigation and inadequate drainage in the flat, low-permeability desert terrain have caused waterlogging and secondary soil salinisation in large parts of the command area, degrading the very agricultural land the canal was meant to improve. Cultivation of water-intensive crops (paddy, sugarcane) in a naturally water-scarce desert ecosystem represents an ecologically inappropriate cropping choice given the region''s fundamental aridity, raising sustainability concerns about long-term water availability, especially as upstream Punjab-Haryana demand on the shared Sutlej-Beas system also grows. The canal has altered local desert ecology, affecting native flora/fauna adapted to arid conditions and traditional pastoral land-use systems, and has raised groundwater tables in some areas to problematic levels while leaving other parts of the command area under-served due to uneven canal-network development.

Critical conclusion: The project illustrates a broader tension in large canal-irrigation schemes -- substantial short/medium-term economic and settlement benefits achieved at the cost of ecologically inappropriate cropping patterns and drainage-management failures, underscoring the need for water-use efficiency reform (drip/sprinkler irrigation, crop-pattern realignment toward less water-intensive options) to make the scheme ecologically sustainable in the long run.', '''Critically examine'' demands the waterlogging/salinisation and inappropriate-cropping-pattern critique, not just a list of economic benefits -- an answer that only praises the canal''s development impact without this ecological critique will underperform. Naming the specific command-area districts (Ganganagar, Bikaner, Jaisalmer) grounds the answer.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q7(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('1b83cf2b-f0a3-4dd2-b58d-87ef11d34a6c', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 25, 'B', '8(a)', 20, 350, 'Why India lags behind many other countries in agricultural productivity? Suggest suitable measures to raise productivity across the regions in a sustainable manner.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('1b83cf2b-f0a3-4dd2-b58d-87ef11d34a6c', 'Introduction: Despite being among the world''s largest agricultural producers by volume, India''s per-hectare agricultural productivity (yield) for most major crops remains well below that of leading producer nations (e.g., rice/wheat yields trail China''s and several developed-country benchmarks), reflecting structural constraints rather than lack of cultivable area.

Reasons for the productivity gap: (i) Small and fragmented landholdings (average holding size continuing to shrink due to inheritance-driven subdivision) limit mechanisation and economies of scale. (ii) Excessive dependence on monsoon rainfall -- only about half of India''s net sown area is irrigated, leaving the rest vulnerable to rainfall variability. (iii) Inadequate and inefficient irrigation infrastructure, with significant water losses in canal systems and over-reliance on groundwater (causing water-table depletion in Punjab-Haryana-western UP). (iv) Regionally skewed input use -- overuse of chemical fertiliser/pesticide in some regions (degrading soil health) alongside under-use in resource-poor eastern/central India. (v) Poor seed-replacement rates and slow adoption of high-yielding/climate-resilient varieties in many regions. (vi) Weak agricultural extension services limiting farmer access to updated technical knowledge and best practices. (vii) Post-harvest losses from inadequate storage, cold-chain and processing infrastructure, reducing effective output value even where production is adequate. (viii) Limited access to institutional credit and crop insurance for many smallholders, discouraging productivity-enhancing investment. (ix) Climate change impacts -- rising temperatures, erratic rainfall, and increasing frequency of extreme weather events disproportionately affecting rain-fed regions.

Sustainable measures to raise productivity: Expanding micro-irrigation (drip/sprinkler) to improve water-use efficiency, particularly critical in water-stressed regions; promoting land consolidation/cooperative and contract-farming models to overcome fragmentation constraints; strengthening agricultural extension and digital advisory services (e.g., Kisan Call Centres, precision-agriculture apps) to close the knowledge gap; expanding climate-resilient and biofortified seed-variety adoption; investing in rural storage, cold-chain and food-processing infrastructure to reduce post-harvest losses; promoting soil-health-card-based balanced fertiliser use and integrated nutrient/pest management to reverse soil degradation while sustaining yield; region-specific cropping-pattern realignment (shifting water-intensive crops away from naturally water-scarce regions, promoting millets/pulses in dryland areas); and improving institutional credit and crop-insurance (PM Fasal Bima Yojana) penetration to de-risk productivity-enhancing investment for smallholders.

Conclusion: A sustainable productivity strategy must be regionally differentiated -- addressing water-management and cropping-pattern issues in over-exploited northwestern India differently from knowledge/infrastructure gaps in eastern India -- rather than applying uniform, one-size-fits-all interventions nationally.', 'This is a comprehensive 20-mark question requiring both diagnosis (why the gap exists) and prescription (sustainable measures) with roughly equal weight, and ideally regionally differentiated recommendations (recognising India''s agro-ecological diversity) rather than a generic national prescription -- a common weakness in otherwise competent answers.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q8(a). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('7cdc2a34-0b40-4e3e-8a40-26a57472ffd0', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 26, 'B', '8(b)', 15, 250, 'Assess the ecotourism potential of Andaman and Nicobar, Lakshadweep islands and highlight the challenges associated with the sustainable development of island territories.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('7cdc2a34-0b40-4e3e-8a40-26a57472ffd0', 'Andaman and Nicobar Islands and Lakshadweep possess exceptional ecotourism potential owing to their pristine coral reefs, mangrove ecosystems, endemic biodiversity (including several endemic bird and marine species), clear-water beaches, and relatively low existing development footprint compared to mainland coastal tourism destinations. Activities such as scuba diving/snorkelling on coral reefs, mangrove-kayaking, marine biodiversity/turtle-nesting observation, and indigenous/tribal cultural tourism (in permitted zones of the Andamans) offer high-value, low-volume tourism models well suited to fragile island ecosystems. Government initiatives promoting island tourism infrastructure (as part of broader island-development and connectivity plans) aim to leverage this potential for economic diversification beyond fishing and limited agriculture.

Challenges to sustainable development: (i) Ecological fragility -- coral reefs are highly sensitive to physical damage (anchor damage, diver contact) and to warming-driven bleaching, meaning uncontrolled tourism growth risks destroying the very asset it depends on. (ii) Carrying-capacity limits -- limited freshwater availability, waste-management capacity, and land area constrain how much tourism infrastructure and visitor volume the islands can sustainably absorb; over-development risks replicating mainland coastal over-tourism problems (as seen at some mainland beach destinations) in a far more ecologically fragile setting. (iii) Waste and sewage management -- remote island locations make solid-waste and wastewater management logistically difficult and costly, with poor management directly threatening marine ecosystems. (iv) Indigenous/tribal rights -- particularly in the Andaman and Nicobar Islands, protecting the rights, land, and isolation of vulnerable tribal groups (e.g., the Jarawa, and the internationally protected isolation of the Sentinelese) must be carefully balanced against tourism-development pressure. (v) Connectivity and logistics -- limited transport infrastructure, while protective of fragility, also constrains economic viability of tourism investment and emergency/disaster response capacity. (vi) Climate vulnerability -- sea-level rise and increasing cyclone intensity pose direct long-term risk to low-lying island tourism infrastructure itself.

A sustainable path requires strict carrying-capacity-based zoning, community/tribal-inclusive governance, and prioritising low-impact, high-value ecotourism models over mass-tourism development.', 'The tribal-rights dimension (Jarawa/Sentinelese protection) is specific to the Andaman context and is a distinguishing point strong answers include; candidates should avoid treating ''ecotourism potential'' and ''sustainability challenges'' as two disconnected halves -- the strongest answers show how the challenges directly threaten the very potential described.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q8(b). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('4ea5df41-7f8d-498e-94e0-ad1971d01e5f', '963c3b26-5d0a-4d54-9f39-760cfeda1427', 27, 'B', '8(c)', 15, 250, 'Describe the regional variations of health indicators among the Indian States.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('4ea5df41-7f8d-498e-94e0-ad1971d01e5f', 'India shows pronounced inter-state variation in key health indicators, generally correlating with broader socioeconomic development levels, historical public-health investment, and governance capacity.

Better-performing states: Southern states (Kerala, Tamil Nadu) and some western/northeastern states show markedly better indicators -- Kerala has India''s lowest Infant Mortality Rate and Maternal Mortality Ratio, highest life expectancy, and near-universal institutional delivery, attributed to historically strong public health investment, high female literacy, and decentralised governance. Tamil Nadu similarly performs well due to sustained public health system investment.

Lagging states: The Empowered Action Group (EAG) states -- Bihar, Uttar Pradesh, Madhya Pradesh, Rajasthan, Odisha, Chhattisgarh, Jharkhand, Uttarakhand -- along with Assam, show persistently higher Infant Mortality Rate, Maternal Mortality Ratio, child stunting/wasting, and lower institutional-delivery and immunisation coverage, reflecting weaker health infrastructure density, lower per-capita health spending, greater rural-remote access barriers, and generally lower female literacy/age-at-marriage, all of which are strongly correlated with health outcomes.

Specific indicator patterns: Total Fertility Rate shows a similar south-low/north-high gradient (Kerala, Tamil Nadu, Andhra Pradesh below replacement level; Bihar, UP still above it), reflecting the same underlying demographic-transition-stage variation. Communicable disease burden (tuberculosis, vector-borne diseases) remains disproportionately concentrated in poorer, less-serviced states, while non-communicable disease burden (diabetes, cardiovascular disease) is rising faster in more urbanised, economically advanced states as they undergo epidemiological transition. Nutritional indicators (stunting, wasting, anaemia among women and children) also show the same south/west-better, north/central-worse general pattern, though pockets of poor performance exist even within otherwise better-performing states.

Implications: These persistent inter-state gaps mean national-average health statistics mask substantial internal disparity, and effective policy (e.g., the National Health Mission''s differential resource allocation toward EAG/high-focus states) must explicitly target lagging states and address the underlying socioeconomic determinants (education, sanitation, income) rather than relying on uniform national programmes alone.', 'Naming the EAG states explicitly and linking outcomes to underlying determinants (female literacy, public health spending, decentralised governance in Kerala''s case) rather than simply listing indicator values state-by-state is what distinguishes analytical depth from rote data recall, which examiners at this level expect.', 'UPSC CSE Mains 2023, Geography Optional Paper II, Section B, Q8(c). Verified verbatim against a scanned official-format bilingual (Hindi/English) 2023 question paper (Chahal Academy archive, printed code SKYC-B-GEO/9), cross-checked against independent question summaries on Anantam IAS (anantamias.com) and Edukemy (edukemy.com) which matched in content and marks.');
